<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue';
import type {Component,Database,InventoryPC} from '../shared/types';
import {componentSchema} from '../shared/component-schema';
import {inspectionCategories,coverageStates} from '../shared/inspection';
import type {InspectionInput} from '../server/inspection';
import ComponentDataEditor from './ComponentDataEditor.vue';
import {componentIdentityLabel} from '../shared/component-identity';
import {useErrorFeedback} from './form-feedback';
const props=defineProps<{pc:InventoryPC;db:Database;revision:string}>();
const emit=defineEmits<{reload:[];notify:[message:string]}>();
const draft=ref<InspectionInput>(fresh()),busy=ref(false),error=ref(''),review=ref<{token:string;units:number;discoveries:number;finished:boolean;warnings:string[]}|null>(null),editingNew=ref<number|null>(null),awaitingReload=ref(false);
const componentEditor=ref<InstanceType<typeof ComponentDataEditor>|null>(null);
const panel=ref('findings');
let expected=props.revision,original=JSON.stringify(draft.value);
function fresh():InspectionInput{const last=props.pc.inspections?.filter(s=>s.method!=='historical').at(-1);return {id:crypto.randomUUID(),sessionId:last&&!last.finished?last.sessionId:crypto.randomUUID(),pcId:props.pc.id,observedAt:new Date().toISOString(),actor:last?.actor||'',method:props.pc.lifecycle==='Retired'?'historical':'opened-case',evidence:'',reportedLocation:'',finished:false,coverage:inspectionCategories.map(category=>({category,status:last?.coverage.find(r=>r.category===category)?.status||'unchecked',notes:last?.coverage.find(r=>r.category===category)?.notes||''})),discoveries:[]};}
watch(()=>props.pc.id,()=>reset());
watch(()=>props.pc,()=>{if(awaitingReload.value){awaitingReload.value=false;reset();}});
function setComponentEditor(value:unknown){componentEditor.value=value as InstanceType<typeof ComponentDataEditor>|null;}
function reset(){draft.value=fresh();expected=props.revision;original=JSON.stringify(draft.value);review.value=null;editingNew.value=null;error.value='';}
watch(draft,()=>review.value=null,{deep:true});
const historical=computed(()=>draft.value.method==='historical');
const observedLocal=computed({get:()=>{const d=new Date(draft.value.observedAt);return Number.isNaN(d.getTime())?'':new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);},set:(value:string)=>{const d=new Date(value);draft.value.observedAt=Number.isNaN(d.getTime())?'':d.toISOString();}});
const labels:Record<string,string>={unchecked:'Not checked',recorded:'Present, identified',unidentified:'Present, identity needed',absent:'Confirmed absent',inaccessible:'Inaccessible / follow-up'};
const coverageHeaders=[{title:'Category',key:'category'},{title:'Coverage',key:'status'},{title:'Observation / follow-up',key:'notes'}];
const known=computed(()=>props.db.inventory.flatMap(stock=>stock.allocations.filter(a=>a.pcId===props.pc.id&&a.state==='installed').map(a=>({stock,a,name:props.db.components.find(c=>c.id===stock.componentId)?.name||stock.componentId}))));
function chooseMethod(method:InspectionInput['method']){if(method==='historical'&&draft.value.discoveries.length){error.value='Save or remove unsaved physical discoveries before switching to historical-only evidence.';return;}draft.value.method=method;draft.value.finished=false;if(method==='historical')panel.value='findings';}
function toggleDetails(index:number){if(componentEditor.value&&!componentEditor.value.canChangeSection())return;editingNew.value=editingNew.value===index?null:index;}
function add(){draft.value.discoveries.push({componentId:'',quantity:1,serial:'',assetTag:'',notes:''});}
function newModel(index:number,placeholder=false){if(componentEditor.value&&!componentEditor.value.canChangeSection())return;const row=draft.value.discoveries[index]!;delete row.componentId;delete row.stockId;row.newComponent={id:crypto.randomUUID(),name:'',category:'Memory',manufacturer:'',model:'',specs:{},source:'',verified:false,identityKind:placeholder?'placeholder':'model'};editingNew.value=index;}
function existingModel(index:number){if(componentEditor.value&&!componentEditor.value.canChangeSection())return;const row=draft.value.discoveries[index]!;delete row.newComponent;row.componentId='';editingNew.value=null;}
function stocks(index:number){const row=draft.value.discoveries[index]!;return props.db.inventory.filter(s=>s.componentId===row.componentId&&s.condition!=='Retired').map(s=>({title:`${s.serial||s.assetTag||s.id} · ${s.condition} · ${s.quantity} total${s.allocations.length?' · already allocated':''}`,value:s.id}));}
function hasUnsavedChanges(){return busy.value||JSON.stringify(draft.value)!==original;}
function confirmDiscard(){if(busy.value)return false;if(hasUnsavedChanges()&&!window.confirm('Discard unsaved inspection observations?'))return false;reset();return true;}
defineExpose({hasUnsavedChanges,confirmDiscard});
async function request(apply=false){if(busy.value)return;if(componentEditor.value&&!await componentEditor.value.validate()){panel.value='findings';await nextTick();await componentEditor.value?.validate();return;}const invalid=draft.value.discoveries.findIndex(row=>row.newComponent&&!componentSchema.safeParse(row.newComponent).success);if(invalid>=0){panel.value='findings';editingNew.value=invalid;await nextTick();await componentEditor.value?.validate();return;}busy.value=true;error.value='';try{const r=await fetch(`/api/inspection/${apply?'apply':'preview'}`,{method:'POST',headers:{'Content-Type':'application/json','If-Match':expected},body:JSON.stringify(apply?{input:draft.value,token:review.value?.token}:draft.value)}),body=await r.json();if(!r.ok)throw Error(body.error||'Inspection could not be saved.');if(apply){review.value=null;awaitingReload.value=true;original=JSON.stringify(draft.value);emit('reload');emit('notify','Inspection saved. New discoveries remain quarantined; lifecycle unchanged.');}else{review.value=body;expected=r.headers.get('X-Workspace-Revision')||expected;}}catch(e){error.value=e instanceof Error?e.message:String(e);review.value=null;}finally{busy.value=false;}}
useErrorFeedback(error);
</script>
<template>
<section class="panel control-stack pa-5" aria-label="PC inspection">
<div class="section-head"><div><h2>Inspect {{pc.name}}</h2><p>Record what is already here. New discoveries are quarantined, even when their model is known. This does not install parts or return a donor to service.</p></div><v-btn :disabled="busy" variant="text" @click="confirmDiscard">Reset unsaved observations</v-btn></div>
<v-alert v-if="error" type="error" role="alert">{{error}}</v-alert>
<v-tabs v-if="!review" v-model="panel" aria-label="Inspection sections" show-arrows><v-tab id="inspection-findings-tab" aria-controls="inspection-findings-panel" value="findings">Observations &amp; parts ({{draft.discoveries.length}})</v-tab><v-tab id="inspection-coverage-tab" aria-controls="inspection-coverage-panel" value="coverage" :disabled="historical">Coverage ({{draft.coverage.filter(r=>!['unchecked','inaccessible'].includes(r.status)).length}}/15)</v-tab><v-tab id="inspection-evidence-tab" aria-controls="inspection-evidence-panel" value="history">Saved evidence ({{pc.inspections?.length||0}})</v-tab></v-tabs>
<template v-if="!review&&panel!=='history'"><div :inert="busy||awaitingReload" class="control-stack">
<div class="form-grid"><v-text-field v-model="draft.actor" label="Inspected by *" /><v-text-field v-model="observedLocal" type="datetime-local" label="Observed at *" hint="Defaults to now. Keep the date of the observation, not the age of the PC." persistent-hint /><v-select :model-value="draft.method" label="Access / evidence method" :items="[{title:'Exterior / labels',value:'exterior'},{title:'OS / inventory report',value:'os-report'},{title:'Opened case',value:'opened-case'},{title:'Test bench',value:'test-bench'},{title:'Historical report only',value:'historical'}]" :disabled="pc.lifecycle==='Retired'" @update:model-value="value=>chooseMethod(value)" /></div>
<v-textarea v-model="draft.evidence" label="Evidence / session notes *" rows="2" hint="Record label transcriptions, report or photo references, access limitations and what remains to inspect. Saving progress creates a permanent entry." persistent-hint />
<v-text-field v-model="draft.reportedLocation" label="Previously reported location / provenance (optional)" hint="Evidence only; this does not change the current physical assignment." persistent-hint />
<v-alert v-if="historical" type="info">Historical notes create no stock and do not complete a survey. Use this for already disposed parts or reports of earlier contents.</v-alert>
<template v-else><section id="inspection-coverage-panel" role="tabpanel" aria-labelledby="inspection-coverage-tab" v-show="panel==='coverage'" class="control-stack"><h3>Category coverage</h3><p>Save partial progress at any time. Confirm absence only after checking; an unidentified present part belongs to a placeholder, not an assumed model. All categories must be accounted for before finishing.</p>
<v-data-table v-table-scroll :headers="coverageHeaders" :items="draft.coverage" :items-per-page="-1" hide-default-footer :mobile="false"><template #caption><caption class="sr-only">Inspection category coverage</caption></template><template #item.status="{item}"><v-select v-model="item.status" :label="`${item.category} coverage`" :items="coverageStates.map(value=>({title:labels[value],value}))" hide-details /></template><template #item.notes="{item}"><v-text-field v-model="item.notes" :label="`${item.category} observation`" hide-details /></template></v-data-table>
<v-checkbox v-model="draft.finished" label="Finish physical enumeration — every category accounted for" hide-details /><p>Finished enumeration can still contain unidentified or untested parts. Commissioning and model-specific planning retain their existing checks.</p></section><section id="inspection-findings-panel" role="tabpanel" aria-labelledby="inspection-findings-tab" v-show="panel==='findings'" class="control-stack"><h3>Already recorded inside this PC</h3><p v-if="!known.length">No physical parts recorded yet. An assumed configuration is not an inventory.</p><ul v-else><li v-for="row in known" :key="row.a.id">{{row.name}} · {{row.a.quantity}} · {{row.stock.serial||row.stock.assetTag||row.stock.id}} · {{row.stock.condition}}</li></ul>
<div class="spec-heading"><h3>Parts found this session</h3><v-btn variant="outlined" :disabled="draft.discoveries.length>=100" @click="add">Record a found part</v-btn></div>
<p>Match existing stock/serials before creating units. Existing custody cannot be silently moved. Wiring and exact placement can be recorded later through inventory.</p>
<section v-for="(row,index) in draft.discoveries" :key="index" class="panel control-stack pa-4" :aria-label="`Found part ${index+1}`"><div class="heading-actions"><v-btn v-if="row.newComponent" variant="text" @click="existingModel(index)">Choose existing catalog type</v-btn><template v-else><v-btn variant="outlined" @click="newModel(index)">Create catalog model</v-btn><v-btn variant="outlined" @click="newModel(index,true)">Record unidentified part</v-btn></template><v-btn color="error" variant="text" @click="draft.discoveries.splice(index,1);editingNew=null">Remove unsaved discovery</v-btn></div>
<template v-if="row.newComponent"><v-btn variant="text" @click="toggleDetails(index)">{{editingNew===index?'Hide':'Edit'}} catalog details: {{row.newComponent.name||'New part'}}</v-btn><ComponentDataEditor v-if="editingNew===index" :ref="setComponentEditor" :component="row.newComponent" :db="db" /><p>Save the readable name, category and model if known. Detailed specifications and verification can wait. This creates a separate catalog type.</p></template>
<template v-else><v-autocomplete v-model="row.componentId" label="Catalog component *" :items="db.components.map(c=>({title:componentIdentityLabel(c),value:c.id}))" clearable @update:model-value="()=>row.stockId=undefined" /><v-select v-model="row.stockId" @update:model-value="()=>{row.serial='';row.assetTag='';}" label="Physical stock identity" :items="[{title:'New physical discovery — not yet recorded',value:undefined},...stocks(index)]" hint="Already allocated units cannot be recorded twice. Resolve custody if a serial belongs to another PC." persistent-hint /></template>
<div class="form-grid"><v-text-field v-model.number="row.quantity" label="Found quantity" type="number" min="1" max="32" /><template v-if="!row.stockId"><v-text-field v-model="row.serial" label="Unit serial (optional; quantity must be 1)" /><v-text-field v-model="row.assetTag" label="Asset / lot tag (optional)" /></template></div><v-textarea v-model="row.notes" label="Part label / observation notes" rows="2" /></section>
</section></template></div><v-btn color="primary" :loading="busy" :disabled="busy||awaitingReload||!draft.actor.trim()||!draft.evidence.trim()" @click="request()">Review inspection save</v-btn></template>
<section v-if="review" class="control-stack" aria-label="Inspection save review"><h3>Review before saving</h3><p>{{review.units}} physical units across {{review.discoveries}} discoveries. {{historical?'Historical evidence only.':review.finished?'Physical enumeration will be marked complete.':'Survey remains partially recorded; resume later.'}}</p><ul><li v-for="(row,index) in draft.discoveries" :key="index">{{row.quantity}} × {{row.newComponent?.name||db.components.find(c=>c.id===row.componentId)?.name}} · {{row.stockId?'Existing stock '+row.stockId:'New quarantined discovery'}} · {{row.serial||row.assetTag||'No unit label'}}</li></ul><p v-for="warning in review.warnings" :key="warning">{{warning}}</p><div class="heading-actions"><v-btn :disabled="busy" variant="outlined" @click="review=null">Back to observations</v-btn><v-btn :loading="busy" :disabled="busy" color="primary" @click="request(true)">Save inspection</v-btn></div></section>
</section>
<section id="inspection-evidence-panel" role="tabpanel" aria-labelledby="inspection-evidence-tab" v-if="!review&&panel==='history'" class="panel control-stack pa-5"><h2>Saved inspection evidence</h2><p v-if="!pc.inspections?.length">No inspection sessions recorded yet.</p><details v-for="entry in [...(pc.inspections||[])].reverse()" :key="entry.id"><summary>{{new Date(entry.observedAt).toLocaleString()}} · {{entry.actor}} · {{entry.method}} · {{entry.finished?'Finished':'Progress / evidence'}}</summary><p>Recorded {{new Date(entry.recordedAt).toLocaleString()}} at {{entry.locationPath||'unassigned'}}. Reported provenance: {{entry.reportedLocation||'None'}}.</p><p>{{entry.evidence}}</p><ul><li v-for="row in entry.discoveries" :key="row.allocationId">{{row.quantity}} {{row.name}} · {{row.notes}}</li><li v-for="row in entry.coverage" :key="row.category">{{row.category}}: {{labels[row.status]}}. {{row.notes}}</li></ul></details></section>
</template>
